          weaponCount: vr.found ? (vr.weaponCount || 0) : 0,
          hasFlowyunPair: vr.found ? !!vr.hasFlowyunPair : false,
          armor: vr.found ? vr.armor : p[5].trim(),
          bao: p[6].trim(),
          injury: vr.found ? vr.injury : p[7].trim(),
          hpCur: p[8].trim(), mpCur: p[9].trim(),
          entry: vr.found ? vr.entry : '', varHP: vr.found ? vr.varHP : null, varMP: vr.found ? vr.varMP : null,
          bonusArts: p[10] ? p[10].trim() : '', bonusBlade: p[11] ? p[11].trim() : ''
        });
        person.aoe = parseAoe(p[12]);
        members.push(person);
      }
      return members;
    }

    var nameA = get('我方名'), nameB = get('敌方名');
    var membersA = parseMembers('我方');
    var membersB = parseMembers('敌方');
    var allMembers = membersA.concat(membersB);

    // 头部：地点时间 + 地形
    var dt = get('地点时间');
    var dp = dt.split(/[·・]/);
    set('.cr-place', (dp[0] || '').trim() || '江湖');
    var tm = dp.slice(1).join(' · ').trim();
    set('.cr-time', tm);
    if (!tm) hide('.cr-sep');
    set('.cr-terrain', get('地形'));
    if (!get('地形')) hide('.cr-sep2');

    // 双方成员列表（含群攻标记）
    function renderList(selList, members) {
      var listEl = q(selList);
      if (listEl) listEl.innerHTML = '';
      if (!members.length) return;
      var html = '';
      for (var i = 0; i < members.length; i++) {
        var p = members[i];
        html += '<div class="cr-member"><span class="m-name">' + p.name + '</span> · ' +
          p.realm + ' · <span class="m-cr">CR ' + p.finalCR + '</span>' +
          (p.aoe > 0 ? ' · <span class="m-aoe">' + aoeLabel(p.aoe) + '</span>' : '') + '<br>' +
          '<span class="m-hpmp">HP ' + p.hpCur + '/' + p.hpMax + ' ｜ MP ' + p.mpCur + '/' + p.mpMax + '</span></div>';
      }
      if (listEl) listEl.innerHTML = html;
    }
    set('.gr-l-name', nameA || '我方');
    set('.gr-r-name', nameB || '敌方');
    renderList('.gr-l-list', membersA);
    renderList('.gr-r-list', membersB);

    // 行动顺序：按 CR 从高到低排，CR 高者先出手
    var orderSorted = allMembers.slice().sort(function (a, b) { return b.finalCR - a.finalCR; });
    function renderOrder() {
      var listEl = q('.gr-order-list');
      if (listEl) listEl.innerHTML = '';
      var html = '';
      for (var i = 0; i < orderSorted.length; i++) {
        var p = orderSorted[i];
        var side = membersA.indexOf(p) >= 0 ? '我方' : '敌方';
        html += '<div class="cr-orderrow"><span class="o-idx">' + (i + 1) + '</span>' +
          '<span class="o-name">' + p.name + '</span>' +
          '<span class="o-side">' + side + '</span>' +
          '<span class="o-cr">CR ' + p.finalCR + '</span>' +
          (p.aoe > 0 ? '<span class="m-aoe">' + aoeLabel(p.aoe) + '</span>' : '') + '</div>';
      }
      if (listEl) listEl.innerHTML = html;
    }
    renderOrder();
    if (!orderSorted.length) hide('.cr-order');

    // 战局/意志/退路
    set('.gr-sum1', get('战局'));
    set('.gr-sum2', get('意志'));
    set('.gr-sum3', get('退路'));
    if (!get('战局') && !get('意志') && !get('退路')) hide('.cr-sum');

    // 战斗思考：脚本给行动顺序 + 成员明细，AI 逐回合 append
    var aiThink = getBlock('战斗思考').replace(/\s*\]\s*$/, '');
    var th = q('.cr-think');
    var thinkText = '';
    var head = '【行动顺序】（脚本按 CR 高→低排，高者先出手）';
    for (var mi = 0; mi < orderSorted.length; mi++) {
      var mp = orderSorted[mi];
      thinkText += (thinkText ? '\n' : '') + (mi + 1) + '. ' + mp.name + '（' + mp.realm + '｜CR ' + mp.finalCR +
        '｜HP ' + mp.hpCur + '/' + mp.hpMax + '｜MP ' + mp.mpCur + '/' + mp.mpMax + '｜' +
        (mp.aoe > 0 ? aoeLabel(mp.aoe) : '无群攻') + '）';
    }
    thinkText = head + '\n' + thinkText;
    aiThink = cleanThink(aiThink, allMembers);
    if (aiThink) thinkText += '\n\n' + aiThink;
    if (thinkText) { th.hidden = false; set('.cr-thinktext', thinkText); }

    // 缺失可见
    var missEl = q('.cr-missing');
    if (missEl) {
      var missing = [];
      if (!membersA.length) missing.push('我方成员[我方成员N]');
      if (!membersB.length) missing.push('敌方成员[敌方成员N]');
      if (!aiThink) missing.push('逐回合过程[战斗思考]');
      if (missing.length) { missEl.textContent = '⚠ 本轮群战缺失：' + missing.join('、') + ' —— 请重新生成，补全成员字段与逐回合过程，按 CR 高→低逐个出手（群攻优先、群攻对 N 目标同时扣血），严禁一次性比 CR。'; missEl.hidden = false; }
    }

    set('.gr-l-mid', get('我方战中语'));
    set('.gr-r-mid', get('敌方战中语'));
    if (!get('我方战中语') && !get('敌方战中语')) hide('.cr-clash');
  }
})();</script>
</body>
</html>
